            primitiveLeaf = true;
            interfaceLeaf = false;
            enumLeaf = false;
            component = nested;
            dimensions++;
          } else {
            if (nested.isInterface()) {
              primitiveLeaf = false;
              interfaceLeaf = true;
              enumLeaf = false;
              component = nested;
              dimensions++;
